import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    last_m, last_o = history[-1]

    # Early game: cooperate, but don't be naive about an immediate defector
    if n <= 2:
        if last_o == 'D':
            return 'D'
        return 'C'

    rounds_left = 100 - n

    # Very trustworthy partner: strong lock-in on cooperation
    if opp_d == 0:
        if rounds_left <= 1:
            return 'D'
        # rare single probe, deterministic cadence so it can recover
        if n >= 20 and n % 31 == 0 and my_d < 2:
            return 'D'
        return 'C'

    opp_rate = opp_c / n

    # Highly cooperative partner: keep cooperation, punish only brief
    if opp_rate >= 0.75:
        if last_o == 'D':
            return 'D'
        # small periodic probe, but avoid when opponent just recovered
        if n >= 15 and n % 37 == 0 and my_d < 3 and opp_rate > 0.85:
            return 'D'
        return 'C'

    # Mostly defecting partner: defect, but keep probing for recovery
    if opp_rate <= 0.2:
        if last_o == 'C':
            # reward any cooperation immediately
            return 'C'
        # rare peace offering to break DD lock
        if n >= 8 and n % 11 == 0:
            return 'C'
        return 'D'

    # Mid-range: forgiving tit-for-tat with short punishment
    if last_o == 'D':
        # If opponent defected after a long cooperation streak, punish once
        streak_c = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                streak_c += 1
            else:
                break
        # streak_c excludes last_o if D; compute prior coop streak
        prior_c = 0
        for i in range(n - 2, -1, -1):
            if history[i][1] == 'C':
                prior_c += 1
            else:
                break
        # Long prior cooperative streak -> one forgiving detour then propose C
        if prior_c >= 5 and last_m == 'C':
            return 'D'
        # If we are the ones who defected into their defection, offer C to reset
        if last_m == 'D':
            if prior_c >= 2:
                return 'C'
            return 'D'
        # Otherwise brief retaliation
        return 'D'

    # Opponent cooperated last round: reciprocate cooperation
    if last_o == 'C':
        # After mutual defection, actively restore cooperation
        if last_m == 'D':
            # we defected and they forgave - lock back into C
            return 'C'
        # Occasional probe against mid-range opponents
        if n >= 25 and n % 43 == 0 and opp_rate > 0.4 and my_d * 3 < my_c:
            return 'D'
        # Endgame: if opponent looks reliable, don't spoil
        if rounds_left <= 2 and opp_rate >= 0.6:
            return 'C'
        return 'C'

    return 'C'
